  // ---------- W12 الالتزام حسب النوع (bars + target line, colour by distance from the target) ----------
  // W12: the type filter keeps only those types
  const w12Items = () => TYPES.map((t, i) => { const v = D.byType[state.scope][i], tn = tone(v); return { i, n: t, v, c: TONE_C[tn], val: `${tn === 'ok' ? ic(I.check, 'db-tn ok') : ic(I.alert, 'db-tn ' + tn)}<b>${v}%</b>` }; }).filter(x => !state.filters.type.length || state.filters.type.includes(x.n)).map((x, k) => ({ ...x, i: k }));
