  document.body.appendChild(tip);
  function showTip(el) {
    let text = el.dataset.tipx;
    if (!text && el.classList.contains('db-trunc') && el.scrollWidth > el.clientWidth + 1) text = el.textContent;
    if (!text) return hideTip();
    tip.textContent = text; tip.classList.add('show');
    const r = el.getBoundingClientRect(), w = tip.offsetWidth, h = tip.offsetHeight;
    tip.style.left = Math.max(8, Math.min(r.left + r.width / 2 - w / 2, innerWidth - w - 8)) + 'px';
    tip.style.top = (r.top - h - 8 < 8 ? r.bottom + 8 : r.top - h - 8) + 'px';
  }
  const hideTip = () => tip.classList.remove('show');
  page.addEventListener('mouseover', e => { const el = e.target.closest('[data-tipx], .db-trunc'); el ? showTip(el) : hideTip(); });
  page.addEventListener('mouseleave', hideTip);
  page.addEventListener('focusin', e => { const el = e.target.closest('[data-tipx]'); el ? showTip(el) : hideTip(); });
  page.addEventListener('focusout', hideTip);
  page.addEventListener('scroll', hideTip, true);

