  // =====================================================================================================
  const SEC_NAME = { W22: 'رصيدي الوظيفي', W19: 'حضوري اليوم', W20: 'إحصائيات بريد الإدارة', W21: 'إحصائيات بريدي', W02: 'بانتظار إجرائك', W18: 'المعاملات حسب مدة الانتظار', W07: 'تصنيف المعاملات', W09: 'التوزيع حسب المصدر', W10: 'مسار المعاملات', W12: 'الالتزام حسب النوع', W13: 'مؤشرات السرعة', W14: 'أداء الإدارات / الفريق', W15: 'أكثر الإدارات تأخيرًا', W16: 'ذروة الوارد' };
  const LOCKED = ['W02'];   // «مقفول، لا يُخفى»
