  const SEC_FIELDS = { W22: [], W19: [], W20: [], W21: [], W02: ['type', 'prio'], W18: ['type', 'prio'], W07: ['prio', 'period'], W09: ['type', 'prio', 'period'], W10: ['type', 'period'], W12: ['period'], W13: ['type', 'period'], W14: ['type', 'period'], W15: ['type'], W16: ['type'] };
