    let h = grp('العنوان', `<input class="db-input" data-set="title" maxlength="60" placeholder="${esc(SEC_NAME[w])}" value="${esc(o.title || '')}" aria-label="عنوان القسم">`);
    if (types) h += grp('نوع الرسم البياني', `<div class="db-types" role="radiogroup" aria-label="نوع الرسم البياني">${types.map(t => `<button type="button" class="db-type${t === ct ? ' on' : ''}" role="radio" aria-checked="${t === ct}" data-settype="${t}">${TYPE_ICON[t]}<span>${TYPE_NAME[t]}</span></button>`).join('')}</div>`);
    if (fields.includes('period')) h += grp('الفترة الزمنية', seg('setperiod', [['board', 'حسب اللوحة'], ...PERIODS], o.period || 'board'));
