    const fl = [fields.includes('type') && sel('type', 'النوع', TYPES.map(t => [t, t])), fields.includes('prio') && sel('prio', 'الأولوية', [['عاجل', 'عاجل'], ['عادي', 'عادي']])].filter(Boolean);
