    if (SER_DEF[w]) h += grp('خيارات العرض', op('legend', 'إظهار وسيلة الإيضاح', true) + op('grid', 'إظهار خطوط الشبكة', true) + op('values', 'إظهار قيم البيانات', false));
    else if (items && ['donut', 'pie', 'stacked'].includes(ct)) h += grp('خيارات العرض', op('legend', 'إظهار وسيلة الإيضاح', true));
    const box = modal.querySelector('.db-m-set'), top = box.scrollTop, fk = document.activeElement && modal.contains(document.activeElement) ? focusSig(document.activeElement) : null;
